import{_ as e,o as l,c as a,a0 as d}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Page 28","description":"","frontmatter":{},"headers":[],"relativePath":"page-28.md","filePath":"page-28.md"}'),i={name:"page-28.md"};function s(r,t,o,n,g,c){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="page-28" tabindex="-1">Page 28 <a class="header-anchor" href="#page-28" aria-label="Permalink to &quot;Page 28&quot;">​</a></h1><h3 id="最短路算法-dijkstra-算法" tabindex="-1">最短路算法 - Dijkstra 算法 <a class="header-anchor" href="#最短路算法-dijkstra-算法" aria-label="Permalink to &quot;最短路算法 - Dijkstra 算法&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">最短路类型</th><th style="text-align:left;">算法名称</th><th style="text-align:left;">时间复杂度</th><th style="text-align:left;">适用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>单源最短路</strong></td><td style="text-align:left;">朴素 Dijkstra 算法</td><td style="text-align:left;">$O(n^2)$</td><td style="text-align:left;">边权均为正，稠密图</td></tr><tr><td style="text-align:left;"><strong>单源最短路</strong></td><td style="text-align:left;">堆优化 Dijkstra 算法</td><td style="text-align:left;">$O(m log n)$</td><td style="text-align:left;">边权均为正，稀疏图</td></tr><tr><td style="text-align:left;"><strong>单源最短路</strong></td><td style="text-align:left;">Bellman-Ford 算法</td><td style="text-align:left;">$O(nm)$</td><td style="text-align:left;">存在负权边</td></tr><tr><td style="text-align:left;"><strong>单源最短路</strong></td><td style="text-align:left;">SPFA 算法</td><td style="text-align:left;">一般 $O(m)$，最坏 $O(nm)$</td><td style="text-align:left;">存在负权边</td></tr><tr><td style="text-align:left;"><strong>多源汇最短路</strong></td><td style="text-align:left;">Floyd 算法</td><td style="text-align:left;">$O(n^3)$</td><td style="text-align:left;">全局最短路</td></tr></tbody></table><ul><li>每走完图都要回到起点/终点，可以通过建反向边实现。</li></ul><h4 id="一、朴素-dijkstra-算法-将图用邻接矩阵存储" tabindex="-1">一、朴素 Dijkstra 算法：将图用邻接矩阵存储 <a class="header-anchor" href="#一、朴素-dijkstra-算法-将图用邻接矩阵存储" aria-label="Permalink to &quot;一、朴素 Dijkstra 算法：将图用邻接矩阵存储&quot;">​</a></h4><p>① 初始化距离，令 <code>dist[1] = 0</code>，其余为 <code>INF</code> ② for i = 1 to n (循环 n 次)</p><ul><li>白点：已确定最短路的点；蓝点：未确定最短路的点</li><li><ol><li>找到蓝点中距离最近的点 t，将 t 设为白点</li></ol></li><li><ol start="2"><li>用 t 松弛其他蓝点的距离：如果 <code>dist[v] &gt; dist[t] + w</code>，则更新 <code>dist[v]</code></li></ol></li></ul><h4 id="二、堆优化-dijkstra-算法-将图用邻接表存储" tabindex="-1">二、堆优化 Dijkstra 算法：将图用邻接表存储 <a class="header-anchor" href="#二、堆优化-dijkstra-算法-将图用邻接表存储" aria-label="Permalink to &quot;二、堆优化 Dijkstra 算法：将图用邻接表存储&quot;">​</a></h4><ul><li><p>通过分析朴素 Dijkstra 的瓶颈为寻找最近点的时间复杂度 <code>O(n)</code>，故予以优化。</p></li><li><p>使用堆优化查找最近点，可将找最近点的复杂度降为 <code>O(log n)</code>。</p></li><li><p>使用优先队列实现，由于优先队列不支持修改堆中元素，故采用惰性删除（即插入新元素，当堆顶元素为过时时直接跳过）。</p></li><li><p>时间复杂度退化为 <code>O(m log n)</code>，由于 <code>m &lt; n^2</code>，故最差 <code>O(m log n)</code>。</p></li><li><p>属于同一量级，一般使用优先队列。</p></li><li><p>由于堆中存在过时元素，当堆顶的最小值可能是已被确认的旧值，通过比较 <code>dist</code> 与堆中存储的数值即可判断是否过时，从而避免重复处理。</p></li></ul>',9)])])}const x=e(i,[["render",s]]);export{h as __pageData,x as default};
